import type { ContestReplayImportMapItem } from "@/types/contest.ts";
import { GetText } from "@/text/library.ts";

// 榜单回放行的身份与展示辅助（收藏键、首 AC 高亮、tiebreak 排序与徽标 tooltip 共用）。
//
// 行键口径与后端 RankKey 一致：回放行 `replay:<replayId>:<sourceUserId>`，真人行 `user:<userId>`；
// 同一用户既在本场真人榜又出现在回放中时，两行键不冲突，避免收藏 / 高亮串号。
// 数据来源只有榜单 rank 链路一处，抽成纯函数是为了可测——键格式写错类型系统不会报错兜住。

/** 回放行身份相关字段的最小结构（原始行 ContestRank 与视图行 ContestRankView 都可传入） */
export interface ReplayRankIdentityRow {
  /** 视图行用户 ID（回放行保留 source_user_id 兜底） */
  userId?: number;
  /** 原始行提交者 ID */
  inserter?: number;
  /** 是否回放行 */
  isReplay?: boolean;
  /** 回放关联 ID */
  replayId?: number;
  /** 源比赛选手 ID */
  sourceUserId?: number;
  /** 源比赛标题 */
  sourceTitle?: string;
  /** 后端下发的复合行键（已下发时直接采用） */
  rankKey?: string;
}

/** 判定是否回放行：仅 isReplay === true 视为回放，旧响应缺字段时按真人行处理 */
export function isReplayRow(row: ReplayRankIdentityRow): boolean {
  return row?.isReplay === true;
}

/** 取行身份的兜底用户 ID：userId 优先，其次 inserter */
function resolveUserId(row: ReplayRankIdentityRow): number {
  return row.userId ?? row.inserter ?? 0;
}

/**
 * 生成行身份键：
 * - 回放行：后端已下发 rank_key 时直接采用，否则按 `replay:<replayId>:<sourceUserId>` 合成；
 * - 真人行：`user:<userId>`。
 */
export function replayRankKey(row: ReplayRankIdentityRow): string {
  if (isReplayRow(row)) {
    if (row.rankKey) {
      return row.rankKey;
    }
    const replayId = row.replayId ?? 0;
    const sourceUserId = row.sourceUserId ?? resolveUserId(row);
    return `replay:${replayId}:${sourceUserId}`;
  }
  return `user:${resolveUserId(row)}`;
}

/**
 * 同 solved / penalty 下的 tiebreak 比较器（可直接传入 Array.prototype.sort）：
 * - 两行均为真人：按 userId 数值升序，保持历史行为，避免 `user:100` 按字典序排在 `user:9` 之前；
 * - 至少一行为回放：退化为行身份键字符串升序（回放复合键与真人 `user:` 键分开排序，结果确定性）。
 */
export function replayRankTiebreak(a: ReplayRankIdentityRow, b: ReplayRankIdentityRow): number {
  if (!isReplayRow(a) && !isReplayRow(b)) {
    const idA = resolveUserId(a);
    const idB = resolveUserId(b);
    return idA - idB;
  }
  const keyA = replayRankKey(a);
  const keyB = replayRankKey(b);
  return keyA < keyB ? -1 : keyA > keyB ? 1 : 0;
}

/**
 * 回放行来源 tooltip 文案：拼接源比赛标题；无源标题时退化为「回放」占位；
 * 真人行返回空串（不展示回放来源 tooltip）。
 */
export function formatReplaySourceTooltip(row: ReplayRankIdentityRow): string {
  if (!isReplayRow(row)) {
    return "";
  }
  const sourceTitle = (row.sourceTitle ?? "").trim();
  if (!sourceTitle) {
    return "回放";
  }
  return `回放自：${sourceTitle}`;
}

// ---------- 编辑页回放关联 Tab：候选与匹配状态展示辅助 ----------

/** 可关联候选条目最小结构（原始候选与 camelCase 视图都可传入） */
export interface EligibleCandidate {
  /** 候选源比赛标题 */
  title: string;
  /** 候选开始时间（已本地化展示串，可选） */
  startTime?: string;
  /** 候选结束时间（已本地化展示串，可选） */
  endTime?: string;
  /** 是否已与本场关联 */
  linked?: boolean;
  /** 中立本体是否与本场已关联回放完全相同（别名候选） */
  isAlias?: boolean;
  /** 候选源本身是不是回放比赛（选择器里加标识便于管理员辨认） */
  isReplay?: boolean;
}

/** 题目匹配状态文案：✓ 题目匹配 / ✗ 题目不一致；编辑页关联列表与榜单面板漂移提示共用口径 */
export function formatReplayProblemMatched(matched: boolean): string {
  return matched ? "✓ 题目匹配" : "✗ 题目不一致";
}

/** 候选是否已关联：已关联候选在选择器中置灰禁用，不允许重复关联 */
export function isEligibleLinked(candidate: Pick<EligibleCandidate, "linked">): boolean {
  return candidate?.linked === true;
}

/** 回放比赛候选的标注文案：回放比赛同样可作为回放源被关联，管理员需要能一眼认出来 */
export const REPLAY_CONTEST_OPTION_MARK = "［回放比赛］";

/**
 * 候选选择器选项文案：标题 + 起止时间区间；回放比赛追加标注；已关联项追加「已关联」。
 * 标注写在 label 字符串里而不是选项插槽：t-select 选中后输入框展示的也是 label，
 * 走插槽时选中态会丢掉标识。
 */
export function formatEligibleOptionLabel(candidate: EligibleCandidate): string {
  const range = [candidate.startTime, candidate.endTime].filter(Boolean).join(" ~ ");
  let text = range ? `${candidate.title}（${range}）` : candidate.title;
  if (candidate.isReplay === true) {
    text += REPLAY_CONTEST_OPTION_MARK;
  }
  return isEligibleLinked(candidate) ? `${text}（已关联）` : text;
}

/** 别名候选创建前的确认提示文案：中立本体与本场已关联回放完全相同，将作为别名展示 */
export const REPLAY_ALIAS_CONFIRM_TEXT = "榜单完全相同，将作为别名展示";

// ---------- 榜单文件导入：题目映射与示例 CSV ----------

/** 题目序号（1 起）转字母编号：1→A，26→Z，27→AA，与比赛题目题号口径一致 */
export function contestProblemLabel(index: number): string {
  let result = "";
  let n = index;
  while (n > 0) {
    n--;
    result = String.fromCharCode(65 + (n % 26)) + result;
    n = Math.floor(n / 26);
  }
  return result;
}

/** 默认题目映射：源题目顺序 ↔ 目标比赛题目顺序（A→第 1 题）。返回源序号与目标序号对。 */
export function defaultImportMapping(sourceCount: number, targetCount: number): ContestReplayImportMapItem[] {
  const items: ContestReplayImportMapItem[] = [];
  const common = Math.min(sourceCount, targetCount);
  for (let i = 0; i < common; i++) {
    items.push({ sourceIndex: i, targetIndex: i + 1 });
  }
  return items;
}

/**
 * 预览弹窗的初始映射（源列序号 → 目标题目序号）：
 * 优先采用后端下发的 problem_map（后端已按题目顺序对齐，可能带人工口径），
 * 缺省时回退到「按顺序一一映射」。返回可直接绑给每个源列下拉框的映射表。
 */
export function resolvePreviewMapping(
  sourceCount: number,
  targetCount: number,
  problemMap: ContestReplayImportMapItem[]
): Record<number, number> {
  const mapping: Record<number, number> = {};
  if (Array.isArray(problemMap) && problemMap.length > 0) {
    for (const item of problemMap) {
      mapping[item.sourceIndex] = item.targetIndex;
    }
    return mapping;
  }
  for (const item of defaultImportMapping(sourceCount, targetCount)) {
    mapping[item.sourceIndex] = item.targetIndex;
  }
  return mapping;
}

/**
 * 预览映射表 → 提交用 problem_map：
 * 只保留已选目标的源列（下拉框清空即「忽略该题」），并按源列序号升序，
 * 避免对象键的整数升序特性在负数/非法键上失效导致请求体顺序不稳定。
 */
export function buildReplayProblemMap(mapping: Record<number, number>): ContestReplayImportMapItem[] {
  if (!mapping) {
    return [];
  }
  const items: ContestReplayImportMapItem[] = [];
  for (const key of Object.keys(mapping)) {
    const sourceIndex = Number(key);
    const targetIndex = Number(mapping[sourceIndex]);
    if (!Number.isInteger(sourceIndex) || !Number.isInteger(targetIndex) || targetIndex <= 0) {
      continue;
    }
    items.push({ sourceIndex, targetIndex });
  }
  items.sort((a, b) => a.sourceIndex - b.sourceIndex);
  return items;
}

/** 示例榜单 CSV 样例行的题目格：AC / 未 AC / 未提交循环排列 */
const SAMPLE_CELLS = ["+12:34", "-2", "."] as const;

/** UTF-8 BOM：让 Excel 打开 CSV 时正确识别中文编码 */
const UTF8_BOM = "\uFEFF";

/**
 * 生成示例榜单 CSV 文本（含 BOM 供 Excel 正确识别中文）。
 * 题目列按本场题目数生成 A/B/C…，附三行可直接改写的样例选手。
 */
export function buildSampleReplayCsv(problemCount: number): string {
  const problemHeader = Array.from({ length: problemCount }, (_, i) => contestProblemLabel(i + 1)).join(",");
  const lines = [
    "# 榜单回放示例：列顺序固定为 Rank,Handle,Nickname,题目列（A,B,C…，与本场题目一一对应）",
    "# 题目格写法：+mm:ss 表示 AC（相对比赛开始的时刻）；-k 表示未 AC（k 次尝试）；. 或空表示未提交",
    `Rank,Handle,Nickname,${problemHeader}`,
  ];

  const sampleRows: Array<[string, string]> = [
    ["alice", "爱丽丝"],
    ["bob", "鲍勃"],
    ["carol", "卡罗尔"],
  ];
  sampleRows.forEach(([handle, nickname], rowIdx) => {
    const cells = Array.from({ length: problemCount }, (_, colIdx) => SAMPLE_CELLS[(rowIdx + colIdx) % SAMPLE_CELLS.length]);
    lines.push(`${rowIdx + 1},${handle},${nickname},${cells.join(",")}`);
  });

  return UTF8_BOM + lines.join("\r\n") + "\r\n";
}

// ---------- 创建页回放暂存：暂存结构、判定与落库失败文案 ----------
//
// 创建页（contestId === 0）没有比赛 ID，源比赛关联只能先暂存在前端，
// 等「创建」成功拿到新比赛 ID 后再逐条落库。判定与文案都是纯逻辑，抽出来是为了可测：
// 置灰判定写错会让同一候选重复暂存，别名判定写错会把两个不同榜单静默合并。

/** 创建页暂存的源比赛回放关联（创建成功后逐条落库） */
export interface PendingReplaySource {
  contestId: number;
  title: string;
  bodyHash?: string;
}

/** 候选是否已暂存（创建期选择器置灰，与编辑态 linked 并列） */
export function isPendingSourceStaged(pending: PendingReplaySource[], contestId: number): boolean {
  if (!Array.isArray(pending)) {
    return false;
  }
  return pending.some((item) => item.contestId === contestId);
}

/**
 * 暂存项中是否已有相同本体指纹（创建期别名判定）。
 * bodyHash 为空一律不算重复：缺省指纹无法证明与本场已有回放同源，
 * 宁可多落一条关联，也不能把两个不同榜单静默合并成别名。
 */
export function hasPendingAliasBodyHash(pending: PendingReplaySource[], bodyHash?: string): boolean {
  if (!bodyHash) {
    return false;
  }
  if (!Array.isArray(pending)) {
    return false;
  }
  return pending.some((item) => item.bodyHash === bodyHash);
}

/** 落库失败明细（label 为回放展示名，code 为后端错误码） */
export interface ReplayApplyFailure {
  label: string;
  code: number | string;
}

/** 失败明细 → 可直接展示的文案行（错误码走 text/library 的 GetText，未登记码回落为错误码） */
export function formatReplayApplyFailures(failures: ReplayApplyFailure[]): string[] {
  if (!Array.isArray(failures)) {
    return [];
  }
  return failures.map((failure) => {
    const [found, text] = GetText(failure.code);
    const reason = found ? text : String(failure.code);
    return `「${failure.label}」关联失败：${reason}`;
  });
}

// ---------- 预览可验证性：成绩矩阵、致命判定、诊断清单 ----------
//
// 上传榜单最危险的地方是「解析成功但结果是错的」：文件写法不合约定时，后端会把认不出的
// 格子按「未提交」处理，预览仍返回成功。管理员如果只看「识别到 N 名选手、M 道题」，
// 完全无法发现成绩全空 / 列错位。这里把「验证」所需的数据算成纯函数，便于单测：
//   - 成绩矩阵：把解析结果按榜单格子口径回显出来，用户一眼能对；
//   - 致命判定：零有效成绩 / 零选手必须硬阻断，不能靠软提示；
//   - 诊断清单：未解析格数、无成绩选手数等「可疑但不阻断」的信号。

/** 预览选手的单题事件（与后端 ReplayImportProblemEventView 对齐的最小结构） */
export interface ReplayPreviewProblemEvent {
  sourceIndex: number;
  status?: string;
  acSeconds?: number | null;
  submits?: Array<{ sec: number; ac: boolean }>;
}

/** 预览选手（最小结构） */
export interface ReplayPreviewParticipant {
  username: string;
  nickname?: string;
  problems: ReplayPreviewProblemEvent[];
}

/** 秒 → `mm:ss` / `h:mm:ss`（与榜单格子 `+mm:ss` 的时钟口径一致） */
export function formatReplayClock(seconds: number): string {
  const total = Number.isFinite(seconds) ? Math.max(0, Math.floor(seconds)) : 0;
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const secs = total % 60;
  const mm = String(minutes).padStart(2, "0");
  const ss = String(secs).padStart(2, "0");
  return hours > 0 ? `${hours}:${mm}:${ss}` : `${mm}:${ss}`;
}

/** 单个题目格回显：AC → `+mm:ss`，未 AC → `-尝试次数`，未提交 → `.`（与导入写法同构） */
export function formatReplayMatrixCell(event?: ReplayPreviewProblemEvent | null): string {
  if (!event) {
    return ".";
  }
  if (event.status === "AC" && typeof event.acSeconds === "number") {
    return `+${formatReplayClock(event.acSeconds)}`;
  }
  const attempts = Array.isArray(event.submits) ? event.submits.filter((submit) => !submit.ac).length : 0;
  return attempts > 0 ? `-${attempts}` : ".";
}

/** 成绩矩阵行 */
export interface ReplayPreviewMatrixRow {
  /** 展示名：昵称优先，昵称空时回落 handle */
  label: string;
  /** 与 sourceProblems 顺序对齐的格子文本 */
  cells: string[];
}

/**
 * 按「源题目列顺序」生成成绩矩阵（预览用）。
 * 只取前 maxRows 行：预览是给人对眼睛的，不是全量榜单；剩余行数由 truncated 告知。
 */
export function buildReplayPreviewMatrix(
  participants: ReplayPreviewParticipant[],
  sourceCount: number,
  maxRows = 8
): { rows: ReplayPreviewMatrixRow[]; total: number; truncated: boolean } {
  const list = Array.isArray(participants) ? participants : [];
  const limit = Math.max(0, maxRows);
  const rows: ReplayPreviewMatrixRow[] = [];
  for (const participant of list.slice(0, limit)) {
    const bySource = new Map<number, ReplayPreviewProblemEvent>();
    for (const event of participant.problems ?? []) {
      bySource.set(event.sourceIndex, event);
    }
    const cells: string[] = [];
    for (let i = 0; i < sourceCount; i++) {
      cells.push(formatReplayMatrixCell(bySource.get(i)));
    }
    const nickname = (participant.nickname ?? "").trim();
    const username = (participant.username ?? "").trim();
    rows.push({ label: nickname || username || "(未命名)", cells });
  }
  return { rows, total: list.length, truncated: list.length > limit };
}

/**
 * 调整题目顺序：把第 index 项上移/下移 delta 位，返回新数组（纯函数，便于单测）。
 * 越界或非法下标原样返回，不抛错——UI 上的「上移/下移」按钮在首尾是禁用的，
 * 这里再兜一层是为了防止快速点击/键盘触发时把数组搞坏。
 */
export function moveReplayProblemOrder(order: number[], index: number, delta: number): number[] {
  const next = Array.isArray(order) ? [...order] : [];
  const target = index + delta;
  if (!Number.isInteger(index) || index < 0 || index >= next.length) {
    return next;
  }
  if (!Number.isInteger(target) || target < 0 || target >= next.length) {
    return next;
  }
  const [item] = next.splice(index, 1);
  next.splice(target, 0, item);
  return next;
}

/** 预览诊断结果 */
export interface ReplayPreviewDiagnosis {
  /** 解析出的选手总数 */
  totalPlayers: number;
  /** 有有效成绩的选手数（可能小于 totalPlayers） */
  scoredPlayers: number;
  /** 榜单题目列数 */
  problemCount: number;
  /** 无法解析的题目格数 */
  unparsedCells: number;
  /** 解析告警条数 */
  warningCount: number;
  /** 致命：不能创建（零选手 / 零有效成绩） */
  hasFatal: boolean;
  /** 致命原因，hasFatal 时非空 */
  fatalReason: string;
  /** 可疑但不阻断的提示（需要显眼展示，让用户自行判断） */
  suspects: string[];
}

/**
 * 预览诊断：致命 / 可疑两级。
 *
 * 致命口径与后端保持一致（后端在解析阶段直接拒绝零有效成绩），这里是**前端兜底**——
 * 旧版本后端或旧预览草稿可能仍然返回「有选手、零成绩」的响应，此时不能放行创建。
 */
export function describeReplayPreview(preview: {
  participants?: ReplayPreviewParticipant[];
  sourceProblems?: unknown[];
  unparsedCells?: number;
  scoredParticipants?: number;
  warnings?: string[];
}): ReplayPreviewDiagnosis {
  const participants = Array.isArray(preview?.participants) ? preview.participants : [];
  const scoredPlayers =
    typeof preview?.scoredParticipants === "number"
      ? preview.scoredParticipants
      : participants.filter((participant) => (participant.problems?.length ?? 0) > 0).length;
  const problemCount = Array.isArray(preview?.sourceProblems) ? preview.sourceProblems.length : 0;
  const unparsedCells = typeof preview?.unparsedCells === "number" ? preview.unparsedCells : 0;
  const warningCount = Array.isArray(preview?.warnings) ? preview.warnings.length : 0;

  const suspects: string[] = [];
  if (unparsedCells > 0) {
    suspects.push(
      `有 ${unparsedCells} 个题目格无法解析，已按「未提交」处理：请确认格子写法是 +mm:ss（通过）/ -次数（未通过）/ . 或留空（未提交）`
    );
  }
  if (scoredPlayers > 0 && scoredPlayers < participants.length) {
    suspects.push(`有 ${participants.length - scoredPlayers} 名选手没有任何成绩，创建后不会出现在榜单上`);
  }
  if (problemCount === 0) {
    suspects.push("文件里没有识别到题目列（表头应为 A、B、C…）");
  }

  let hasFatal = false;
  let fatalReason = "";
  if (participants.length === 0) {
    hasFatal = true;
    fatalReason = "文件里没有解析出任何选手，请检查选手列（Handle / 用户名）";
  } else if (scoredPlayers === 0) {
    hasFatal = true;
    fatalReason = "所有选手都没有可识别的成绩，无法生成回放；请检查题目格的写法（+mm:ss / -次数 / .）";
  }

  return {
    totalPlayers: participants.length,
    scoredPlayers,
    problemCount,
    unparsedCells,
    warningCount,
    hasFatal,
    fatalReason,
    suspects,
  };
}

